async function e(e){let t=await fetch(e,{headers:{Accept:`application/json`},credentials:`same-origin`});if(!t.ok)throw Error(`HTTP ${String(t.status)}`);return await t.json()}async function t(e,t){let n=await fetch(e,{method:`POST`,headers:{Accept:`application/json`,"Content-Type":`application/json`},credentials:`same-origin`,body:JSON.stringify(t)});if(!n.ok)throw Error(`HTTP ${String(n.status)}`);return await n.json()}export{t as n,e as t};